"""Registrar leituras e inspeção visual do lote B5-03 (registro 130)."""
from pathlib import Path
from collections import Counter
import json,hashlib
A=Path(__file__).resolve().parent;R=A.parents[1]
def load(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,d):(A/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
m=load(A/'amostra.json');changes=load(A/'alteracoes.json');ins=load(A/'imagens-inspecionadas-primeira-prova-visual.json')['primeira_prova'];N=len(m['paginas']);assert N==20
cur={i:sha(A/f'pagina-{i:02}.png') for i in range(1,N+1)};same={i for i in cur if ins[str(i)]==cur[i]};assert same==set(range(1,21)),same
notes={1:'Abertura do Amontoado e quadro das duas fichas.',2:'Fim do quadro, ficha adquirida e condução do encontro.',3:'Golpe que permite a tentativa, tabela de destruição, submissão e registro adquirido.',4:'Fim do quadro adquirido, religar e especial com reserva vazia.',5:'Tentar antes da derrota e registro para a próxima mesa.',6:'Abertura do Escriba e ficha no nível 5.',7:'Famílias, agulhas e quadro da Agulha perfurante.',8:'Executar especial e quadro do Retrato de referência.',9:'Pedido além dos limites, turno e evolução para o nível 6.',10:'Próximos níveis em quadros e registro.',11:'Abertura do Transporte e ficha da Mula.',12:'Albarda de papel em quadro e a conta de um passageiro.',13:'Quadro do passageiro, montar e tarefa que continua.',14:'Inconsciência, especial aguardando e recolher; quadro do que fica.',15:'Morte do invocador e maldição livre.',16:'Registro da retirada; abertura do Vigia.',17:'Ficha do Vigia no nível 9 e habilidades.',18:'Trabalho, entrega e primeira manifestação; começo da evolução.',19:'Evolução, reconstrução e transferência.',20:'Corpo de criação e conferência final.'}
save('revisao-final.json',{'registro':130,'pdf':m['pdf'],'pdf_sha256':m['pdf_sha256'],'passagens_textuais':[{'passagem':1,'registros':sum(c['passagem']==1 for c in changes),'escopo':'Leitura integral das quatro fontes e das regras citadas, quatro cópias, remissões e clareza.'},{'passagem':2,'registros':sum(c['passagem']==2 for c in changes),'escopo':'Leitura da prova completa, trechos alterados no contexto e varredura de crase, repetições e termos de produção; nenhuma alteração necessária.'}],'ajuste_de_diagramacao':'Sem ajuste necessário; rótulos presos aos títulos.','paginas':[{'pagina':i,'imagem':str((A/f'pagina-{i:02}.png').relative_to(R)),'imagem_sha256':cur[i],'inspecionada':True,'metodo':'Inspeção direta após o último ajuste' if False else 'Inspeção direta na primeira prova; imagem idêntica (mesmo hash)','observacao':notes[i]} for i in range(1,N+1)],'limites':['Sem leitor humano independente ou terceira leitura integral.','A última página termina com meia coluna; reavaliar o fechamento na integração.','Não conclui a revisão visual global ou a comparação final do livro inteiro.']})
ranges={'s052':[1,5],'s053':[6,11],'s054':[11,16],'s055':[16,20]};rows=[]
for f in m['fontes']:
 counts=Counter(str(c['passagem']) for c in changes if c['fonte']==f['fonte']);rows.append({'id':f['fonte_id'],'fonte_original':f['fonte_original'],'fonte_revisada':f['fonte'],'sha256_original':f['sha256_original'],'sha256_revisado':f['sha256'],'passagem_1':'Original integral e regras pertinentes consultados.','passagem_2_paginas_da_prova':ranges[f['fonte_id']],'paginas_na_prova_final':ranges[f['fonte_id']],'registros_por_passagem':dict(counts),'estado':'duas passagens locais; conferir conjunto antes de integrar'})
save('leitura-por-caso.json',{'registro':130,'casos':rows,'limites':'Sem terceira leitura integral, teste humano ou nova simulação.'})
save('mapa-do-lote.json',{'registro':130,'lote':'B5-03','casos':[f['fonte_id'] for f in m['fontes']],'pdf_parcial':m['pdf'],'paginas':N,'casos_revistos_total':59,'casos_pendentes':0,'lotes_pendentes':0,'consultas_complementares_pendentes':17,'etapa_6':'em andamento','proximo_lote':'consultas complementares','modelo_recomendado':'Claude Opus 5.5 (equivalente no plano: GPT-6.1 Sol)','esforco_recomendado':'alto','edicao_integrada':'preservada; não substituída'})
print(json.dumps({'paginas_inspecionadas':N,'registros':len(changes),'casos':4},ensure_ascii=False))
